from typing import Optional, List

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

class Solution:
    def leafSimilar(self, root1: Optional[TreeNode], root2: Optional[TreeNode]) -> bool:
        def get_leaves(node: Optional[TreeNode]) -> List[int]:
            if not node:
                return []
            if not node.left and not node.right:
                return [node.val]
            return get_leaves(node.left) + get_leaves(node.right)

        return get_leaves(root1) == get_leaves(root2)

class Solution {
public:
    void getLeaves(TreeNode* node, vector<int>& leaves) {
        if (!node) return;
        if (!node->left && !node->right) {
            leaves.push_back(node->val);
            return;
        }
        getLeaves(node->left, leaves);
        getLeaves(node->right, leaves);
    }

    bool leafSimilar(TreeNode* root1, TreeNode* root2) {
        vector<int> l1, l2;
        getLeaves(root1, l1);
        getLeaves(root2, l2);
        return l1 == l2;
    }
};

class Solution {
    private void getLeaves(TreeNode node, List<Integer> leaves) {
        if (node == null) return;
        if (node.left == null && node.right == null) {
            leaves.add(node.val);
            return;
        }
        getLeaves(node.left, leaves);
        getLeaves(node.right, leaves);
    }

    public boolean leafSimilar(TreeNode root1, TreeNode root2) {
        List<Integer> l1 = new ArrayList<>();
        List<Integer> l2 = new ArrayList<>();
        getLeaves(root1, l1);
        getLeaves(root2, l2);
        return l1.equals(l2);
    }
}

var leafSimilar = function(root1, root2) {
    function getLeaves(node, leaves = []) {
        if (!node) return leaves;
        if (!node.left && !node.right) {
            leaves.push(node.val);
            return leaves;
        }
        getLeaves(node.left, leaves);
        getLeaves(node.right, leaves);
        return leaves;
    }
    const l1 = getLeaves(root1);
    const l2 = getLeaves(root2);
    return l1.length === l2.length && l1.every((v, i) => v === l2[i]);
};
